import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { readFile } from 'node:fs/promises';
import { join, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { committedTree } from '../dist/tools/measurement-checkout.js';
import { writeReport } from '../dist/tools/scrub-results.js';
import { sourceCostArtifact } from '../dist/tools/source-cost-artifact.js';
import { verifySourceCostFrozenC } from '../dist/tools/source-cost-control.js';
import { readSourceCostWorkerProof, verifySourceCostWorkerSubject } from '../dist/tools/source-cost-worker-proof.js';

const [preparationArg, artifactArg, controlArtifactArg, controlCheckoutArg, historicalArg, outputArg] = process.argv.slice(2);
assert.ok(preparationArg && artifactArg && controlArtifactArg && controlCheckoutArg && historicalArg && outputArg);
const directory = resolve(preparationArg), artifact = resolve(artifactArg),
  controlArtifact = resolve(controlArtifactArg), controlCheckout = resolve(controlCheckoutArg),
  historical = resolve(historicalArg), output = resolve(outputArg), root = process.cwd();
const hash = bytes => createHash('sha256').update(bytes).digest('hex');
const preparation = JSON.parse(await readFile(join(directory, 'preparation.json'), 'utf8'));
assert.deepEqual(committedTree(root), preparation.candidate);
assert.deepEqual(committedTree(controlCheckout), preparation.control);
assert.deepEqual(committedTree(historical), preparation.baseline);
const proofPath = join(directory, 'worker-proof.json');
const proofSHA256 = hash(await readFile(proofPath));
assert.equal(proofSHA256, preparation.workerProofSHA256);
const proof = await readSourceCostWorkerProof(root, proofPath, proofSHA256, historical);
const oldCore = await import(pathToFileURL(join(historical, 'dist/src/core.js')).href);
const oldBackends = await import(pathToFileURL(join(historical, 'dist/src/backends.js')).href);
const indexPath = 'experiments/unification/frontend-a0/inputs/index.json';
assert.equal(hash(await readFile(indexPath)), preparation.inputIndexSHA256);
const units = JSON.parse(await readFile(indexPath, 'utf8'));
const arms = ['old-canonical', 'old-dense', 'flat-ts-control', 'flat-a0', 'flat-a0-control'];
const fields = ['modulePreparationMs', 'postCheckMs', 'frontendMs', 'emitCMs', 'pipelineMs',
  'beforePreparationRssBytes', 'beforePreparationHeapUsedBytes', 'beforePreparationExternalBytes',
  'initialPeakRssBytes', 'initialRssBytes', 'frontendRssBytes', 'frontendHeapUsedBytes',
  'frontendHeapTotalBytes', 'frontendArrayBufferBytes', 'frontendExternalBytes',
  'frontendPeakRssBytes', 'peakRssBytes', 'rssBytes', 'heapUsedBytes', 'heapTotalBytes',
  'arrayBufferBytes', 'externalBytes', 'wasmLinearMemoryBytes'];
const rows = [];
const startedAt = new Date().toISOString();
for (const unit of units) {
  const inputPath = join(directory, unit.input);
  const raw = await readFile(inputPath);
  assert.equal(hash(raw), preparation.preparedInputs[unit.input]);
  const input = JSON.parse(raw.toString('utf8'));
  const expected = oldBackends.compile(oldCore.parseAndValidate(input.canonical), 'c').text;
  verifySourceCostFrozenC(expected, unit.outputSHA256);
  for (const arm of arms) {
    const control = arm === 'flat-a0-control';
    const child = spawnSync(process.execPath, [
      resolve('dist/tools/source-cost-worker.js'), arm, inputPath,
      control ? controlArtifact : artifact, historical,
      control ? controlCheckout : root, proofPath, proofSHA256,
    ], { cwd: root, encoding: 'utf8', timeout: 240000, maxBuffer: 8 * 1024 * 1024 });
    assert.equal(child.status, 0, `${unit.unit}/${arm}: ${child.error ?? ''}\n${child.stderr}`);
    const cell = JSON.parse(child.stdout);
    assert.equal(cell.outputSha256, hash(expected));
    assert.equal(cell.outputBytes, Buffer.byteLength(expected));
    assert.deepEqual(cell.preload, control ? preparation.controlArtifact : preparation.artifact);
    for (const field of fields) assert.ok(Number.isFinite(cell[field]) && cell[field] >= 0, field);
    for (const phase of ['modulePreparationCpu', 'frontendCpu'])
      for (const field of ['user', 'system'])
        assert.ok(Number.isFinite(cell[phase][field]) && cell[phase][field] >= 0, `${phase}.${field}`);
    rows.push({ unit: unit.unit, arm, outputSHA256: cell.outputSha256,
      outputBytes: cell.outputBytes, artifactSHA256: cell.preload.artifactSha256 });
    await writeReport(output, {
      schema: 1, scope: 'Correctness smoke only. Phase and memory observations are validated for presence and discarded; no performance or memory comparison.',
      startedAt, candidate: preparation.candidate, baseline: preparation.baseline,
      control: preparation.control, workerProofSHA256: proofSHA256,
      verifiedNumericFields: fields, timeoutMs: 240000, rows,
    });
    console.log(`PASS ${unit.unit}/${arm}`);
  }
}
assert.equal(rows.length, 30);
assert.deepEqual(await readSourceCostWorkerProof(root, proofPath, proofSHA256, historical), proof);
verifySourceCostWorkerSubject(await sourceCostArtifact(artifact), proof.subjects.candidate);
verifySourceCostWorkerSubject(await sourceCostArtifact(controlArtifact), proof.subjects.control);
await writeReport(output, {
  schema: 1, scope: 'Correctness smoke only. Phase and memory observations are validated for presence and discarded; no performance or memory comparison.',
  startedAt, finishedAt: new Date().toISOString(), candidate: preparation.candidate,
  baseline: preparation.baseline, control: preparation.control, workerProofSHA256: proofSHA256,
  verifiedNumericFields: fields, timeoutMs: 240000, finalImmutabilityCheck: 'pass', rows,
});
console.log('PASS all 30 strict worker checksums; no performance comparison');
